// Enumerate four old red links removed and two old blue links added.
use std::io::{self,BufRead};
type G=[u32;27];type E=(usize,usize);
fn flip(g:&mut G,(i,j):E){g[i]^=1<<j;g[j]^=1<<i;}
fn blue(g:&G,mut p:u32,k:u32)->bool{if k==0{return true}while p.count_ones()>=k{let i=p.trailing_zeros() as usize;p&=p-1;if blue(g,p&!g[i],k-1){return true}}false}
fn adds(g:&mut G,p:u32,ds:&mut [usize;27],need:&mut [i32;9],pairs:&[E],k:usize,c:&mut [u64;6]){for (pos,&(i,j)) in pairs.iter().enumerate(){let (x,y)=(ds[i],ds[j]);if need[x]<=0||need[y]<=if x==y{1}else{0}{continue}if g[i]&g[j]&p!=0{continue}flip(g,(i,j));ds[i]+=1;ds[j]+=1;need[x]-=1;need[y]-=1;if k==2{adds(g,p,ds,need,&pairs[pos+1..],1,c)}else{c[3]+=1;if !blue(g,p,8){c[4]+=1;let f=(0..27).filter(|&i|p>>i&1!=0&&ds[i]==4).fold(0,|v,i|v|1<<i);if (0..27).all(|i|f>>i&1==0||(g[i]&f).count_ones()<=1){c[5]+=1;}}}need[x]+=1;need[y]+=1;ds[i]-=1;ds[j]-=1;flip(g,(i,j));}}
fn remove(g:&mut G,p:u32,d:&mut [usize;27],h:&mut [i32;9],es:&[E],k:usize,plus:&[E],c:&mut [u64;6]){if k==0{c[1]+=1;let mut need=[0;9];let mut carry=0;for t in 0..8{carry+=h[t]-match t{4=>6,6=>12,7=>8,_=>0};if carry<0{return}need[t]=carry;}debug_assert_eq!(need.iter().sum::<i32>(),4);c[2]+=1;adds(g,p,d,&mut need,plus,2,c);return}for (pos,&(i,j)) in es.iter().enumerate(){if es.len()-pos<k{break}for v in [i,j]{h[d[v]]-=1;d[v]-=1;h[d[v]]+=1;}flip(g,(i,j));remove(g,p,d,h,&es[pos+1..],k-1,plus,c);flip(g,(i,j));for v in [i,j]{h[d[v]]-=1;d[v]+=1;h[d[v]]+=1;}}}
fn main(){let mut c=[0u64;6];for s in io::stdin().lock().lines(){let s=s.unwrap();let bytes=s.as_bytes();let mut g=[0;27];let mut t=0;for j in 0..27{for i in 0..j{if (bytes[1+t/6]-63)>>(5-t%6)&1==1{flip(&mut g,(i,j))}t+=1}}for z in 0..27{if g[z].count_ones()!=7{continue}let p=((1<<27)-1)^(1<<z);let mut es=vec![];let mut plus=vec![];let mut d=[0;27];let mut h=[0;9];for i in 0..27{if i==z{continue}d[i]=(g[i]&p).count_ones() as usize;h[d[i]]+=1;for j in 0..i{if j==z{continue}if g[i]>>j&1!=0{es.push((i,j))}else{plus.push((i,j))}}}assert_eq!(es.len(),78);c[0]+=1;remove(&mut g,p,&mut d,&mut h,&es,4,&plus,&mut c);}}println!("{:?}",c)}
